w('src/app/login/page.tsx','''"use client";import {useState} from 'react';import Link from 'next/link';import {ArrowUpRight,LockKeyhole,LoaderCircle} from 'lucide-react';import {login} from './actions';export default function Login(){const[error,setError]=useState('');const[busy,setBusy]=useState(false);return <main className="login-page"><section className="login-story"><Link href="/" className="wordmark">HEXA<span>PLUS</span><sup>+</sup></Link><div><span className="eyebrow">THE HEXA PLUS WORKSPACE</span><h1>Good ideas.<br/>Connected people.<br/><span>Work that moves.</span></h1><p>The private workspace for the team behind the work.</p></div><span className="login-foot">DIGITAL SOLUTIONS + MARKETING · MINYA, EGYPT</span></section><section className="login-panel"><Link href="/" className="back-home">Back to website <ArrowUpRight size={16}/></Link><div className="login-form-wrap"><img src="/hexa-plus-original.jpg" width="100" height="100" alt="HEXA PLUS original logo"/><span className="eyebrow"><LockKeyhole size={14}/> PRIVATE WORKSPACE</span><h2>Welcome back.</h2><p>Sign in with your team account to continue.</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');const result=await login(new FormData(e.currentTarget));if(result?.error)setError(result.error);setBusy(false)}}><label className="form-field"><span>Email address</span><input type="email" name="email" required autoComplete="username" placeholder="you@company.com"/></label><label className="form-field"><span>Password</span><input type="password" name="password" required autoComplete="current-password" placeholder="Your password"/></label>{error&&<p role="alert" className="field-error">{error}</p>}<button className="primary-link" disabled={busy}>{busy?<LoaderCircle size={18} className="spin"/>:<>Sign in <ArrowUpRight size={18}/></>}</button></form><p className="form-note">Access is managed by your workspace administrator.<br/>No public registration.</p></div></section></main>}''')
w('src/components/dashboard-shell.tsx','''"use client";import Link from 'next/link';import {usePathname} from 'next/navigation';import {createContext,useContext,useEffect,useState} from 'react';import {LayoutDashboard,Users,Contact,KanbanSquare,CheckSquare,BriefcaseBusiness,Palette,Megaphone,Receipt,FolderOpen,Settings,Activity,Bell,Search,Sun,Moon,Menu,X,ArrowUpRight,LogOut,ChevronRight,Languages,ShieldCheck,CalendarDays} from 'lucide-react';import {logout} from '@/app/login/actions';import {modules} from '@/lib/modules';
const Locale=createContext({ar:false,t:(en:string,arabic:string)=>en});export const useLocale=()=>useContext(Locale);
const icons:Record<string,React.ElementType>={clients:Contact,leads:KanbanSquare,projects:BriefcaseBusiness,tasks:CheckSquare,team:Users,services:Palette,portfolio:FolderOpen,content:CalendarDays,campaigns:Megaphone,invoices:Receipt,files:FolderOpen,settings:Settings,activity:Activity,notifications:Bell,permissions:ShieldCheck};
const groups=[['WORKSPACE',['clients','leads','projects','tasks','team']],['CONTENT & GROWTH',['services','portfolio','content','campaigns','social']],['BUSINESS',['invoices','payments','expenses','files']],['ADMINISTRATION',['notifications','activity','settings','roles','permissions']]] as [string,string[]][];
export function DashboardShell({children,name,permissions,unread}:{children:React.ReactNode;name:string;permissions:string[];unread:number}){const path=usePathname();const[ar,setAr]=useState(false);const[light,setLight]=useState(false);const[menu,setMenu]=useState(false);const[q,setQ]=useState('');useEffect(()=>{setAr(localStorage.getItem('hexa-lang')==='ar');setLight(localStorage.getItem('hexa-theme')==='light')},[]);const t=(en:string,arabic:string)=>ar?arabic:en;const allowed=(key:string)=>permissions.includes('*')||permissions.includes(modules[key]?.permission+'.read');const active=path.split('/')[2];return <Locale.Provider value={{ar,t}}><div className={'dashboard '+(light?'light':'')} dir={ar?'rtl':'ltr'}><a href="#dashboard-main" className="skip-link">Skip to workspace content</a>{menu&&<button className="sidebar-backdrop" aria-label="Close menu" onClick={()=>setMenu(false)}/>}<aside className={'dashboard-sidebar '+(menu?'visible':'')}><Link href="/dashboard" className="dashboard-brand"><img src="/hexa-plus-original.jpg" width="44" height="44" alt="HEXA PLUS original logo"/><span>HEXA<span>PLUS</span><small>{t('COMPANY WORKSPACE','مساحة عمل الشركة')}</small></span></Link><Link href="/dashboard" className={'sidebar-link '+(!active?'active':'')} onClick={()=>setMenu(false)}><LayoutDashboard size={18}/>{t('Overview','نظرة عامة')}</Link>{groups.map(([title,keys])=><div className="sidebar-group" key={title}><span>{title==='WORKSPACE'?t(title,'مساحة العمل'):title==='CONTENT & GROWTH'?t(title,'المحتوى والنمو'):title==='BUSINESS'?t(title,'الأعمال'):t(title,'الإدارة')}</span>{keys.filter(allowed).map(key=>{const Icon=icons[key]||FolderOpen;return <Link href={'/dashboard/'+key} key={key} className={'sidebar-link '+(active===key?'active':'')} onClick={()=>setMenu(false)}><Icon size={17}/>{ar?modules[key].ar:modules[key].label}{key==='notifications'&&unread>0&&<b>{unread}</b>}</Link>})}</div>)}<div className="sidebar-footer"><Link href="/" target="_blank">{t('View website','عرض الموقع')}<ArrowUpRight size={16}/></Link><div className="team-identity"><span>{name.slice(0,1).toUpperCase()}</span><div><strong>{name}</strong><small>{t('HEXA PLUS team','فريق هيكسا بلس')}</small></div><form action={logout}><button title={t('Sign out','تسجيل الخروج')}><LogOut size={17}/></button></form></div></div></aside><div className="dashboard-body"><header className="dashboard-topbar"><div className="breadcrumb"><button className="dashboard-menu" aria-label="Open sidebar" onClick={()=>setMenu(!menu)}>{menu?<X/>:<Menu/>}</button><Link href="/dashboard">{t('Workspace','مساحة العمل')}</Link><ChevronRight size={14}/><span>{active?(ar?modules[active]?.ar:modules[active]?.label)||active:t('Overview','نظرة عامة')}</span></div><div className="topbar-actions"><form className="global-search" action="/dashboard/search"><Search size={15}/><input name="q" value={q} onChange={e=>setQ(e.target.value)} placeholder={t('Search workspace...','ابحث في مساحة العمل...')} aria-label={t('Search workspace','ابحث في مساحة العمل')}/><kbd>↵</kbd></form><button aria-label={t('Switch to Arabic','Switch to English')} title={t('Switch to Arabic','Switch to English')} onClick={()=>{setAr(!ar);localStorage.setItem('hexa-lang',!ar?'ar':'en')}}><Languages size={18}/></button><button aria-label={t('Toggle theme','تغيير المظهر')} onClick={()=>{setLight(!light);localStorage.setItem('hexa-theme',!light?'light':'dark')}}>{light?<Moon size={18}/>:<Sun size={18}/>}</button><Link href="/dashboard/notifications" className="notification-button" aria-label={t('Notifications','الإشعارات')}><Bell size={18}/>{unread>0&&<i/>}</Link><span className="profile-avatar">{name.slice(0,1).toUpperCase()}</span></div></header><main id="dashboard-main" className="dashboard-main">{children}</main><footer className="dashboard-footer"><span>HEXA PLUS / {t('Company workspace','مساحة عمل الشركة')}</span><span>{t('Private. Connected. Yours.','خاص. متصل. لك.')}</span></footer></div></div></Locale.Provider>}
''')
w('src/app/dashboard/layout.tsx','''import {requireUser} from '@/lib/auth';import {DashboardShell} from '@/components/dashboard-shell';import {redirect} from 'next/navigation';export const dynamic='force-dynamic';export const metadata={title:'Workspace',robots:{index:false,follow:false}};export default async function DashboardLayout({children}:{children:React.ReactNode}){const{db,user}=await requireUser();const{data:p}=await db.from('profiles').select('name,status,role_id,roles(name)').eq('id',user.id).single();if(!p||p.status!=='active')redirect('/login');const{data:grants}=await db.from('role_permissions').select('permissions(name)').eq('role_id',p.role_id);const role=p.roles as unknown as {name:string};const permissions=role?.name==='super_admin'?['*']:(grants||[]).map(g=>(g.permissions as unknown as {name:string})?.name).filter(Boolean);const{count}=await db.from('notifications').select('*',{count:'exact',head:true}).eq('recipient_id',user.id).is('read_at',null);return <DashboardShell name={p.name} permissions={permissions} unread={count||0}>{children}</DashboardShell>}''')
